      { question: "What did Jonathan and David do at the stone Ezel before David fled from Saul?", choices: ["They made a covenant of friendship and said farewell", "They fought together against the Philistines", "They buried Saul's spear", "They built an altar"], answer: "They made a covenant of friendship and said farewell", reference: "1 Samuel 20:19, 41-42", category: "Events", difficulty: "hard" },
      { question: "What did David do to avoid being recognized while seeking refuge with King Achish of Gath?", choices: ["He pretended to be insane", "He disguised himself as a woman", "He shaved his head", "He claimed to be a Philistine soldier"], answer: "He pretended to be insane", reference: "1 Samuel 21:13", category: "Events", difficulty: "medium" },
      { question: "What happened when Saul, in a jealous rage, ordered the priests of Nob killed for aiding David?", choices: ["Doeg the Edomite carried out the massacre", "The priests fled and were spared", "Jonathan refused and was punished", "Samuel intervened and stopped it"], answer: "Doeg the Edomite carried out the massacre", reference: "1 Samuel 22:18", category: "Events", difficulty: "hard" },
      { question: "What happened when David found Saul sleeping in a cave at En-gedi?", choices: ["David cut off a piece of Saul's robe instead of killing him", "David killed Saul", "David woke Saul and they reconciled", "David's men killed Saul against his wishes"], answer: "David cut off a piece of Saul's robe instead of killing him", reference: "1 Samuel 24:4-7", category: "Events", difficulty: "medium" },
      { question: "What happened after Nabal insulted David's messengers and refused to give provisions?", choices: ["Abigail intervened with gifts, and Nabal later died, after which David married her", "David killed Nabal personally", "Nabal repented and gave David his fortune", "Saul punished Nabal for the insult"], answer: "Abigail intervened with gifts, and Nabal later died, after which David married her", reference: "1 Samuel 25:18-42", category: "Events", difficulty: "medium" },
      { question: "What did David do when he found Saul asleep in his camp a second time, guarded by Abner?", choices: ["He took Saul's spear and water jug but spared his life again", "He killed Abner", "He killed Saul", "He woke the whole camp"], answer: "He took Saul's spear and water jug but spared his life again", reference: "1 Samuel 26:7-12", category: "Events", difficulty: "hard" },
      { question: "What happened when Saul, desperate before his final battle, consulted the medium at Endor?", choices: ["The spirit of Samuel appeared and prophesied Saul's death", "Nothing appeared", "Samuel appeared and blessed Saul", "An angel appeared instead"], answer: "The spirit of Samuel appeared and prophesied Saul's death", reference: "1 Samuel 28:11-19", category: "Events", difficulty: "medium" },
      { question: "What happened to Saul and his sons at the battle of Mount Gilboa?", choices: ["They were killed by the Philistines; Saul fell on his own sword", "They won the battle decisively", "Saul was captured alive", "Jonathan survived but Saul died"], answer: "They were killed by the Philistines; Saul fell on his own sword", reference: "1 Samuel 31:1-6", category: "Events", difficulty: "medium" },
      { question: "What did the men of Jabesh-gilead do after recovering the bodies of Saul and his sons from Beth-shan?", choices: ["They burned the bodies and buried the bones, then fasted seven days", "They left the bodies on the wall", "They sent the bodies to David", "They buried them in Jerusalem"], answer: "They burned the bodies and buried the bones, then fasted seven days", reference: "1 Samuel 31:12-13", category: "Events", difficulty: "hard" },
      { question: "What happened to the Philistines and their idol Dagon's temple after they captured the ark, prompting them to return it?", choices: ["They were struck with tumors/plague in multiple cities", "They were swallowed by the earth", "They went blind", "Their crops failed"], answer: "They were struck with tumors/plague in multiple cities", reference: "1 Samuel 5:6-12", category: "Events", difficulty: "medium" },
      { question: "What happened when the women sang of David after his victories, comparing him favorably to Saul?", choices: ["Saul became jealous and sought to kill David", "Saul rewarded David further", "Saul made David his heir", "The people rejected David"], answer: "Saul became jealous and sought to kill David", reference: "1 Samuel 18:6-9", category: "Events", difficulty: "medium" },
      { question: "How did David escape from his house when Saul sent men to kill him there?", choices: ["Michal lowered him through a window", "He hid in the wilderness", "Jonathan smuggled him out", "He disguised himself as a servant"], answer: "Michal lowered him through a window", reference: "1 Samuel 19:12", category: "Events", difficulty: "medium" }
